I'll create a comprehensive solution for adding action buttons to headings. Let me implement this step by step.

## 1. First, modify `MarkdownViewer.vue` to add action buttons to headings:

```vue src/components/MarkdownViewer.vue
<script setup>
import { full as emoji } from 'markdown-it-emoji'
import MarkdownIt from 'markdown-it'
import highlight from 'markdown-it-highlightjs'
import InteractiveTable from './InteractiveTable.vue'
import HeadingActions from './HeadingActions.vue'
</script>

<template>
  <div class="text-wrap overflow-y-auto prose max-w-full">
    <!-- Render markdown content with mixed elements -->
    <div class="space-y-4">
      <div 
        v-for="(element, idx) in renderedElements" 
        :key="`element-${idx}`"
        @click="handleClick"
      >
        <!-- Markdown/HTML content with heading action buttons -->
        <div 
          v-if="element.type === 'markdown'"
          class="heading-container relative"
        >
          <div 
            v-html="element.content"
            @mouseenter="onHeadingHover"
            @mouseleave="hoveredHeadingId = null"
          ></div>

          <!-- Heading action buttons overlay -->
          <HeadingActions
            v-if="hoveredHeadingId"
            :headingId="hoveredHeadingId"
            :headingLevel="getHeadingLevel(hoveredHeadingId)"
            :documentId="documentId"
            :fullContent="text"
            @copy-chapter="onCopyChapter"
            @create-task="onCreateTask"
          />
        </div>

        <!-- Table with toggle header -->
        <div 
          v-else-if="element.type === 'table'"
          class="space-y-2"
        >
          <div class="flex items-center justify-end">
            <label class="toggle toggle-sm text-base-content cursor-pointer">
              <input 
                type="checkbox"
                :checked="element.viewMode === 'interactive'"
                @change="toggleTableMode(idx, element.viewMode === 'markdown' ? 'interactive' : 'markdown')"
              />
              <svg 
                aria-label="Interactive" 
                xmlns="http://www.w3.org/2000/svg" 
                viewBox="0 0 24 24"
                class="w-4 h-4"
              >
                <g
                  stroke-linejoin="round"
                  stroke-linecap="round"
                  stroke-width="2"
                  fill="none"
                  stroke="currentColor"
                >
                  <rect x="3" y="3" width="18" height="18" rx="2" />
                  <path d="M9 11h6m-6 4h6" />
                </g>
              </svg>
              <svg
                aria-label="Standard"
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 24 24"
                class="w-4 h-4"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <rect x="3" y="3" width="18" height="18" rx="2" />
                <path d="M7 7h10M7 11h10M7 15h4" />
              </svg>
            </label>
          </div>

          <!-- Interactive table component -->
          <InteractiveTable 
            v-if="element.viewMode === 'interactive'"
            :initial-data="element.data"
            :table-index="idx"
            @update-table="handleTableUpdate"
          />

          <!-- Standard markdown table -->
          <div 
            v-else
            v-html="element.markdownHtml"
          ></div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import MarkdownIt from 'markdown-it'
import { full as emoji } from 'markdown-it-emoji'
import highlight from 'markdown-it-highlightjs'
import InteractiveTable from './InteractiveTable.vue'
import HeadingActions from './HeadingActions.vue'

function createMd(documentId) {
  const md = new MarkdownIt({ html: true, linkify: true, typographer: true })
  md.use(emoji)
  md.use(highlight)

  const defaultHeadingRenderer = md.renderer.rules.heading_open || function(tokens, idx, options, env, self) {
    return self.renderToken(tokens, idx, options)
  }

  // Add IDs to heading elements - CRITICAL for DocumentSummary scroll-to functionality
  md.renderer.rules.heading_open = function(tokens, idx, options, env, self) {
    const token = tokens[idx]
    const inlineToken = tokens[idx + 1]
    if (inlineToken && inlineToken.children) {
      const text = inlineToken.children
        .filter(t => t.type === 'text' || t.type === 'code_inline')
        .map(t => t.content)
        .join('')

      // Generate slug matching DocumentSummary format
      const slug = text
        .toLowerCase()
        .replace(/[^\w\s-]/g, '')
        .trim()
        .replace(/\s+/g, '-')

      // Create anchor ID with documentId scope
      const anchor = documentId ? `${documentId}-${slug}` : slug

      token.attrSet('id', anchor)
      token.attrSet('class', 'heading-anchor scroll-mt-4 group relative')
    }
    return defaultHeadingRenderer(tokens, idx, options, env, self)
  }

  md.core.ruler.push('table_marker', (state) => {
    let rowIdx = 0
    for (let i = 0; i < state.tokens.length; i++) {
      const token = state.tokens[i]
      if (token.type === 'table_open') {
        token.attrSet('data-interactive-table', 'true')
        rowIdx = 0
      }
      if (token.type === 'tr_open') {
        token.attrSet('data-row', rowIdx.toString())
        rowIdx++
      }
      if (token.type === 'th_open' || token.type === 'td_open') {
        const colIdx = token.map ? state.tokens.slice(0, i).filter(t => t.type === token.type && t.map && t.map[0] === token.map[0]).length : 0
        token.attrSet('data-col', colIdx.toString())
      }
    }
  })

  const defaultFenceRenderer = md.renderer.rules.fence || function(tokens, idx, options, env, self) {
    return self.renderToken(tokens, idx, options)
  }

  // Add IDs to code block anchors - CRITICAL for DocumentSummary scroll-to functionality
  md.renderer.rules.fence = function(tokens, idx, options, env, self) {
    const token = tokens[idx]
    const info = token.info ? token.info.trim() : ''
    const infoMatch = info.match(/^(\w+)\s+([\w\-_.\/]+)$/)
    const filePath = infoMatch ? infoMatch[2] : null
    const rendered = defaultFenceRenderer(tokens, idx, options, env, self)

    if (!filePath) return rendered

    // Generate slug matching DocumentSummary format
    const slug = filePath
      .toLowerCase()
      .replace(/[^\w\s\-./]/g, '')
      .trim()
      .replace(/[\s/]+/g, '-')

    // Create anchor ID with documentId scope
    const anchor = documentId ? `${documentId}-${slug}` : slug
    return `<div id="${anchor}" class="code-block-anchor scroll-mt-4">${rendered}</div>`
  }

  return md
}

const FILE_PATH_REGEX = /(?<=^|[\s(,>])((?:\.{1,2}\/|\/)?(?:[\w\-_.]+\/)+[\w\-_.]+\.(?:js|ts|vue|py|java|cpp|c|h|cs|go|rb|rs|php|html|css|scss|json|yaml|yml|md|txt|sh|bash|env|toml|xml|sql|graphql|proto|ipynb|jsx|tsx|mjs|cjs|svelte|kotlin|swift|dart))(?=[\s),<]|$)/g

function addFileUploadIcons(html) {
  return html.replace(
    FILE_PATH_REGEX,
    (match) =>
      `<span
        class="file-path-upload-btn underline ml-1 cursor-pointer inline-flex items-center align-middle"
        data-file-path="${match}"
        title="Add '${match}' to chat files"
      ><i class="fa-solid fa-file-arrow-up"></i>&nbsp;${match}</span>`
  )
}

function parseTableFromHtml(tableHtml) {
  if (typeof document === 'undefined') return null
  const parser = new DOMParser()
  const doc = parser.parseFromString(tableHtml, 'text/html')
  const table = doc.querySelector('table')
  if (!table) return null

  const data = []
  const rows = table.querySelectorAll('tr')

  rows.forEach(tr => {
    const cells = tr.querySelectorAll('td, th')
    const row = Array.from(cells).map(cell => cell.textContent.trim())
    if (row.length > 0) data.push(row)
  })

  return data.length > 0 ? data : null
}

export default {
  props: {
    text: { type: String, default: '' },
    files: { type: Array, default: null },
    documentId: { type: String, default: '' }
  },
  emits: ['add-file', 'table-updated', 'copy-chapter', 'create-task'],
  components: {
    InteractiveTable,
    HeadingActions
  },
  data() {
    return {
      renderedElements: [],
      hoveredHeadingId: null,
      headingLevels: {}
    }
  },
  computed: {
    sanitizedText() {
      let text = ''
      if (this.text) {
        text = this.text
          .replace('```thymeleaf', '```html')
          .replace('```md', '')
      }
      return text
    }
  },
  watch: {
    text() {
      this.renderContent()
    },
    documentId() {
      this.renderContent()
    }
  },
  mounted() {
    this.renderContent()
  },
  methods: {
    renderContent() {
      try {
        const md = createMd(this.documentId)
        const textWithLinks = this.sanitizedText.replace(
          /`((?:\/[^\s:]+)+)(?::(\d+))?`/g,
          (match, filePath, lineNumber) => {
            const slashCount = (filePath.match(/\//g) || []).length
            if (slashCount < 2) return match
            const lineInfo = lineNumber ? `:${lineNumber}` : ''
            return `<a class="file-link btn btn-link" href="${filePath}${lineInfo}">${filePath}${lineInfo}</a>`
          }
        )
        const rendered = md.render(textWithLinks)
        this.parseElements(rendered)
        this.captureHeadingLevels()
      } catch (ex) {
        console.error("Message can't be rendered", this.text)
        this.renderedElements = []
      }
    },
    parseElements(html) {
      const elements = []
      const tableRegex = /<table[^>]*>[\s\S]*?<\/table>/g
      let lastIndex = 0
      let match

      // Extract all tables with their positions
      const tables = []
      while ((match = tableRegex.exec(html)) !== null) {
        tables.push({
          start: match.index,
          end: match.index + match[0].length,
          html: match[0],
          data: parseTableFromHtml(match[0])
        })
      }

      // Split content by tables
      tables.forEach((table, idx) => {
        // Add markdown content before table
        if (table.start > lastIndex) {
          const mdHtml = html.substring(lastIndex, table.start).trim()
          if (mdHtml) {
            elements.push({
              type: 'markdown',
              content: addFileUploadIcons(mdHtml)
            })
          }
        }

        // Add table element with view mode toggle
        if (table.data && table.data.length > 0) {
          elements.push({
            type: 'table',
            data: table.data,
            markdownHtml: table.html,
            viewMode: 'markdown'
          })
        }

        lastIndex = table.end
      })

      // Add remaining markdown content
      if (lastIndex < html.length) {
        const mdHtml = html.substring(lastIndex).trim()
        if (mdHtml) {
          elements.push({
            type: 'markdown',
            content: addFileUploadIcons(mdHtml)
          })
        }
      }

      this.renderedElements = elements.length > 0 ? elements : [{ 
        type: 'markdown', 
        content: addFileUploadIcons(html) 
      }]
    },
    captureHeadingLevels() {
      this.$nextTick(() => {
        const headings = document.querySelectorAll('[id^="' + this.documentId + '"]')
        headings.forEach(heading => {
          const tag = heading.tagName.toLowerCase()
          const level = parseInt(tag[1])
          this.headingLevels[heading.id] = level
        })
      })
    },
    onHeadingHover(event) {
      const heading = event.target.closest('h1, h2, h3, h4, h5, h6')
      if (heading && heading.id) {
        this.hoveredHeadingId = heading.id
      }
    },
    getHeadingLevel(headingId) {
      return this.headingLevels[headingId] || 1
    },
    extractChapterContent(headingId, headingLevel) {
      const lines = this.text.split('\n')
      const startLineIndex = this.findHeadingLineIndex(headingId, lines)

      if (startLineIndex === -1) return ''

      let endLineIndex = lines.length
      const startHeadingLevel = headingLevel

      // Find next heading of same or higher level (lower number = higher level)
      for (let i = startLineIndex + 1; i < lines.length; i++) {
        const match = lines[i].match(/^(#{1,6})\s+/)
        if (match) {
          const level = match[1].length
          if (level <= startHeadingLevel) {
            endLineIndex = i
            break
          }
        }
      }

      return lines.slice(startLineIndex, endLineIndex).join('\n')
    },
    findHeadingLineIndex(headingId, lines) {
      // Extract heading text from ID
      const headingText = headingId.replace(this.documentId + '-', '').replace(/-/g, ' ')

      for (let i = 0; i < lines.length; i++) {
        const match = lines[i].match(/^(#{1,6})\s+(.+)$/)
        if (match) {
          const lineText = match[2]
            .toLowerCase()
            .replace(/[^\w\s-]/g, '')
            .trim()
            .replace(/\s+/g, '-')

          if (lineText === headingText) {
            return i
          }
        }
      }
      return -1
    },
    onCopyChapter(chapterData) {
      this.$emit('copy-chapter', chapterData)
    },
    onCreateTask(taskData) {
      this.$emit('create-task', taskData)
    },
    toggleTableMode(idx, mode) {
      if (this.renderedElements[idx] && this.renderedElements[idx].type === 'table') {
        this.renderedElements[idx].viewMode = mode
      }
    },
    handleTableUpdate(payload) {
      this.$emit('table-updated', payload)
    },
    handleClick(event) {
      const btn = event.target.closest('.file-path-upload-btn')
      if (!btn) return
      event.preventDefault()
      event.stopPropagation()
      const filePath = btn.getAttribute('data-file-path')
      if (filePath) {
        this.$emit('add-file', filePath)
      }
    }
  }
}
</script>
```

## 2. Create new `HeadingActions.vue` component:

```vue src/components/HeadingActions.vue
<script setup>
</script>

<template>
  <div class="absolute -right-16 top-0 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity z-10">
    <button
      class="btn btn-xs btn-ghost tooltip tooltip-left"
      data-tip="Copy chapter"
      @click="handleCopyChapter"
      title="Copy this chapter and all content until the next heading of same level"
    >
      <i class="fa-solid fa-copy text-primary"></i>
    </button>
    <button
      class="btn btn-xs btn-ghost tooltip tooltip-left"
      data-tip="Create task"
      @click="handleCreateTask"
      title="Create a task from this chapter"
    >
      <i class="fa-solid fa-tasks text-warning"></i>
    </button>
  </div>
</template>

<script>
export default {
  props: {
    headingId: { type: String, required: true },
    headingLevel: { type: Number, required: true },
    documentId: { type: String, required: true },
    fullContent: { type: String, required: true }
  },
  emits: ['copy-chapter', 'create-task'],
  methods: {
    extractChapterContent() {
      const lines = this.fullContent.split('\n')
      const startLineIndex = this.findHeadingLineIndex(lines)

      if (startLineIndex === -1) return ''

      let endLineIndex = lines.length

      // Find next heading of same or higher level
      for (let i = startLineIndex + 1; i < lines.length; i++) {
        const match = lines[i].match(/^(#{1,6})\s+/)
        if (match) {
          const level = match[1].length
          if (level <= this.headingLevel) {
            endLineIndex = i
            break
          }
        }
      }

      return lines.slice(startLineIndex, endLineIndex).join('\n')
    },
    findHeadingLineIndex(lines) {
      // Extract heading text from ID
      const headingText = this.headingId
        .replace(this.documentId + '-', '')
        .replace(/-/g, ' ')

      for (let i = 0; i < lines.length; i++) {
        const match = lines[i].match(/^(#{1,6})\s+(.+)$/)
        if (match) {
          const lineText = match[2]
            .toLowerCase()
            .replace(/[^\w\s-]/g, '')
            .trim()
            .replace(/\s+/g, '-')

          if (lineText === headingText) {
            return i
          }
        }
      }
      return -1
    },
    getHeadingText(lines, lineIndex) {
      const match = lines[lineIndex].match(/^(#{1,6})\s+(.+)$/)
      return match ? match[2] : 'Chapter'
    },
    handleCopyChapter() {
      const chapterContent = this.extractChapterContent()
      const lines = this.fullContent.split('\n')
      const startLineIndex = this.findHeadingLineIndex(lines)
      const headingText = this.getHeadingText(lines, startLineIndex)

      this.$emit('copy-chapter', {
        headingId: this.headingId,
        headingText,
        headingLevel: this.headingLevel,
        content: chapterContent
      })
    },
    handleCreateTask() {
      const chapterContent = this.extractChapterContent()
      const lines = this.fullContent.split('\n')
      const startLineIndex = this.findHeadingLineIndex(lines)
      const headingText = this.getHeadingText(lines, startLineIndex)

      this.$emit('create-task', {
        headingId: this.headingId,
        headingText,
        headingLevel: this.headingLevel,
        content: chapterContent
      })
    }
  }
}
</script>
```

## 3. Update `Document.vue` to handle heading actions:

```vue src/components/document/Document.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue'
import Code from '../Code.vue'
</script>

<template>
  <div class="flex flex-col @container/document">
    <div v-for="block in blocks" :key="block.hash">
      <MarkdownViewer
        :files="files"
        :documentId="documentId"
        v-if="block.renderer === 'md'"
        :text="block.content"
        @add-file="$emit('add-file', $event)"
        @copy-chapter="handleCopyChapter"
        @create-task="handleCreateTask"
      />
      <Code
        :text="block.content"
        :text-language="block.type"
        :fileName="block.fileName"
        :files="files"
        :project="docProject"
        :finished="block.finished"
        :chat="chat"
        :message="message"
        @generate-code="$emit('generate-code', $event)"
        @reload-file="$emit('reload-file', { file: $event, message })"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @add-file="$emit('add-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
        v-else
      />
    </div>
  </div>
</template>

<script>
function generateHash(str) {
  let hash = 0
  for (const char of str) {
    hash = (hash << 5) - hash + char.charCodeAt(0)
    hash |= 0
  }
  return hash
}

function getRenderer(blockType) {
  if (['markdown', 'md'].includes(blockType)) return 'md'
  if (['html'].includes(blockType)) return blockType
  return 'code'
}

function parseContent(content, loading) {
  const blocks = []
  const lines = content.split('\n')
  let currentType = 'markdown'
  let currentContent = []
  let currentFileName = ''
  let nestingDepth = 0

  function setAllFinished() {
    blocks.forEach(b => b.finished = true)
  }

  function addBlock() {
    const blockContent = currentContent.join('\n')
    const hash = generateHash(blockContent)
    setAllFinished()
    blocks.push({
      type: currentType,
      content: blockContent,
      hash,
      fileName: currentFileName,
      renderer: getRenderer(currentType),
      finished: false
    })
    currentType = 'markdown'
    currentContent = []
    currentFileName = ''
  }

  for (const line of lines) {
    const openMatch = line.match(/^```([^\s]+)\s*(.*)$/)
    const closeMatch = line === '```'

    if (nestingDepth === 0 && openMatch) {
      if (currentContent.length) addBlock()
      nestingDepth = 1
      currentType = openMatch[1]
      currentFileName = openMatch[2] || ''
    } else if (nestingDepth === 1 && closeMatch) {
      addBlock()
      nestingDepth = 0
    } else if (nestingDepth >= 1 && openMatch) {
      nestingDepth++
      currentContent.push(line)
    } else if (nestingDepth > 1 && closeMatch) {
      nestingDepth--
      currentContent.push(line)
    } else {
      currentContent.push(line)
    }
  }

  if (currentContent.length) addBlock()
  if (!loading) setAllFinished()
  return blocks
}

export default {
  props: {
    content: { type: String, default: '' },
    files: { type: Array, default: null },
    project: { type: Object, default: null },
    chat: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    documentId: { type: String, default: '' },
    message: { type: Object, default: null }
  },
  emits: [
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'sub-task',
    'copy-chapter',
    'create-task'
  ],
  data() {
    return {}
  },
  computed: {
    blocks() {
      return parseContent(this.content || '', this.loading)
    },
    docProject() {
      return this.project || this.$project
    }
  },
  methods: {
    handleCopyChapter(chapterData) {
      this.$emit('copy-chapter', chapterData)
    },
    handleCreateTask(taskData) {
      this.$emit('create-task', taskData)
    }
  }
}
</script>
```

