        <!-- Message content area — ref used by DocumentSummary to scroll within -->
        <div 
          ref="contentArea"
          @copy.stop="onMessageCopy"
          @mouseup="onContentMouseUp"
          :class="[
            'max-w-full border-slate-300/20 relative', 
