                  <i class="fa-solid fa-file-arrow-up"></i>
                </div>
                <div class="overflow-hidden">
                  {{ file.split('/').reverse()[0] }}
                </div>
              </div>
              <div class="click hover:text-error" @click.stop="$emit('remove-file', file)">
