      .toLowerCase()
      .replace(/[^\w\s\-./]/g, '')
      .trim()
      .replace(/[\s/]+/g, '-')

    const anchor = documentId ? `${documentId}-${slug}` : slug
    return `<div id="${anchor}" class="code-block-anchor scroll-mt-4">${rendered}</div>`
  }

  return md
}

const FILE_PATH_REGEX = /(?<=^|[\s(,>])((?:\.{1,2}\/|\/)?(?:[\w\-_.]+\/)+[\w\-_.]+\.(?:js|ts|vue|py|java|cpp|c|h|cs|go|rb|rs|php|html|css|scss|json|yaml|yml|md|txt|sh|bash|env|toml|xml|sql|graphql|proto|ipynb|jsx|tsx|mjs|cjs|svelte|kotlin|swift|dart))(?=[\s),<]|$)/g

function addFileUploadIcons(html) {
  return html.replace(
    FILE_PATH_REGEX,
    (match) =>
      `<span
        class="file-path-upload-btn underline ml-1 cursor-pointer inline-flex items-center align-middle"
        data-file-path="${match}"
        title="Add '${match}' to chat files"
      ><i class="fa-solid fa-file-arrow-up"></i>&nbsp;${match}</span>`
  )
}

function parseTableFromHtml(tableHtml) {
  if (typeof document === 'undefined') return null
  const parser = new DOMParser()
  const doc = parser.parseFromString(tableHtml, 'text/html')
  const table = doc.querySelector('table')
  if (!table) return null

  const data = []
  const rows = table.querySelectorAll('tr')

  rows.forEach(tr => {
    const cells = tr.querySelectorAll('td, th')
    const row = Array.from(cells).map(cell => cell.textContent.trim())
    if (row.length > 0) data.push(row)
  })

  return data.length > 0 ? data : null
}

export default {
  props: {
    text: { type: String, default: '' },
    files: { type: Array, default: null },
    documentId: { type: String, default: '' }
  },
  emits: ['add-file', 'table-updated', 'copy-chapter', 'create-task'],
  components: {
    InteractiveTable,
    HeadingRenderer
  },
  data() {
    return {
      renderedElements: [],
      headingLevels: {}
    }
  },
  computed: {
    sanitizedText() {
      let text = ''
      if (this.text) {
        text = this.text
          .replace('```thymeleaf', '```html')
          .replace('```md', '')
      }
      return text
    }
  },
  watch: {
    text() {
      this.renderContent()
    },
    documentId() {
      this.renderContent()
    }
  },
  mounted() {
    this.renderContent()
  },
  methods: {
    renderContent() {
      try {
        const md = createMd(this.documentId)
        const textWithLinks = this.sanitizedText.replace(
          /`((?:\/[^\s:]+)+)(?::(\d+))?`/g,
          (match, filePath, lineNumber) => {
            const slashCount = (filePath.match(/\//g) || []).length
            if (slashCount < 2) return match
            const lineInfo = lineNumber ? `:${lineNumber}` : ''
            return `<a class="file-link btn btn-link" href="${filePath}${lineInfo}">${filePath}${lineInfo}</a>`
          }
        )
        const rendered = md.render(textWithLinks)
        this.parseElements(rendered)
        this.captureHeadingLevels()
      } catch (ex) {
        console.error("Message can't be rendered", this.text)
        this.renderedElements = []
      }
    },
    parseElements(html) {
      const elements = []
      const tableRegex = /<table[^>]*>[\s\S]*?<\/table>/g
      const headingRegex = /<h([1-6]) id="([^"]+)"[^>]*>[\s\S]*?<\/h\1>/g

      let lastIndex = 0
      let tableMatch, headingMatch

      // Extract all tables
      const tables = []
      const tableRegexCopy = new RegExp(tableRegex.source, tableRegex.flags)
      while ((tableMatch = tableRegexCopy.exec(html)) !== null) {
        tables.push({
          start: tableMatch.index,
          end: tableMatch.index + tableMatch[0].length,
          html: tableMatch[0],
          data: parseTableFromHtml(tableMatch[0])
        })
      }

      // Extract all headings
      const headings = []
      const headingRegexCopy = new RegExp(headingRegex.source, headingRegex.flags)
      while ((headingMatch = headingRegexCopy.exec(html)) !== null) {
        headings.push({
          start: headingMatch.index,
          end: headingMatch.index + headingMatch[0].length,
          html: headingMatch[0],
          level: parseInt(headingMatch[1]),
          id: headingMatch[2]
        })
      }

      // Merge and sort all special elements
      const specialElements = [...tables, ...headings].sort((a, b) => a.start - b.start)

      // Build element array
      specialElements.forEach((element) => {
        // Add markdown content before this element
        if (element.start > lastIndex) {
          const mdHtml = html.substring(lastIndex, element.start).trim()
          if (mdHtml) {
            elements.push({
              type: 'markdown',
              content: addFileUploadIcons(mdHtml)
            })
          }
        }

        // Add the special element
        if (element.level !== undefined) {
          // It's a heading
          elements.push({
            type: 'heading',
            html: element.html,
            headingId: element.id,
            headingLevel: element.level
          })
        } else if (element.data) {
          // It's a table
          elements.push({
            type: 'table',
            data: element.data,
            markdownHtml: element.html,
            viewMode: 'markdown'
          })
        }

        lastIndex = element.end
      })

      // Add remaining markdown content
      if (lastIndex < html.length) {
        const mdHtml = html.substring(lastIndex).trim()
        if (mdHtml) {
          elements.push({
            type: 'markdown',
            content: addFileUploadIcons(mdHtml)
          })
        }
      }

      this.renderedElements = elements.length > 0 ? elements : [{ 
        type: 'markdown', 
        content: addFileUploadIcons(html) 
      }]
    },
    captureHeadingLevels() {
      this.$nextTick(() => {
        const headings = document.querySelectorAll('[id^="' + this.documentId + '"][class*="heading-anchor"]')
        headings.forEach(heading => {
          const tag = heading.tagName.toLowerCase()
          const level = parseInt(tag[1])
          this.headingLevels[heading.id] = level
        })
      })
    },
    onCopyChapter(chapterData) {
      this.$emit('copy-chapter', chapterData)
    },
    onCreateTask(taskData) {
      this.$emit('create-task', taskData)
    },
    toggleTableMode(idx, mode) {
      if (this.renderedElements[idx] && this.renderedElements[idx].type === 'table') {
        this.renderedElements[idx].viewMode = mode
      }
    },
    handleTableUpdate(payload) {
      this.$emit('table-updated', payload)
    },
    handleClick(event) {
      const btn = event.target.closest('.file-path-upload-btn')
      if (!btn) return
      event.preventDefault()
      event.stopPropagation()
      const filePath = btn.getAttribute('data-file-path')
      if (filePath) {
        this.$emit('add-file', filePath)
      }
    }
  }
}
</script>

