<script setup>
import ChapterBlock from './ChapterBlock.vue'
import Code from '../Code.vue'
</script>

<template>
  <div class="flex flex-col @container/document">
    <ChapterBlock
      v-for="chapter in chapters"
      :key="chapter.hash"
      :chapter="chapter"
      :files="files"
      :documentId="documentId"
      :docProject="docProject"
      :chat="chat"
      :message="message"
      @add-file="$emit('add-file', $event)"
      @copy-chapter="handleCopyChapter"
      @create-task="handleCreateTask"
      @generate-code="$emit('generate-code', $event)"
      @reload-file="$emit('reload-file', { file: $event, message })"
      @open-file="$emit('open-file', $event)"
      @save-file="$emit('save-file', $event)"
      @edit-message="$emit('edit-message', $event)"
      @sub-task="$emit('sub-task', $event)"
    />
  </div>
</template>

<script>
function generateHash(str) {
  let hash = 0
  for (const char of str) {
    hash = (hash << 5) - hash + char.charCodeAt(0)
    hash |= 0
  }
  return hash
}

function isHeading(line) {
  return /^#{1,6}\s+/.test(line)
}

function getHeadingLevel(line) {
  const match = line.match(/^(#+)\s+/)
  return match ? match[1].length : 0
}

function parseChapters(content, loading) {
  const chapters = []
  const lines = content.split('\n')
  let currentChapter = null

  for (const line of lines) {
    if (isHeading(line)) {
      if (currentChapter && currentChapter.content.length > 0) {
        const chapterContent = currentChapter.content.join('\n')
        chapters.push({
          ...currentChapter,
          content: chapterContent,
          hash: generateHash(chapterContent)
        })
      }

      const headingLevel = getHeadingLevel(line)
      const headingText = line.replace(/^#+\s+/, '').trim()
      currentChapter = {
        level: headingLevel,
        title: headingText,
        content: [line],
        finished: false
      }
    } else if (currentChapter) {
      currentChapter.content.push(line)
    } else {
      if (!chapters.length) {
        currentChapter = {
          level: 0,
          title: 'Introduction',
          content: [line],
          finished: false
        }
      } else {
        currentChapter.content.push(line)
      }
    }
  }

  if (currentChapter && currentChapter.content.length > 0) {
    const chapterContent = currentChapter.content.join('\n')
    chapters.push({
      ...currentChapter,
      content: chapterContent,
      hash: generateHash(chapterContent)
    })
  }

  // Mark all as finished if not loading
  if (!loading) {
    chapters.forEach(c => c.finished = true)
  } else if (chapters.length > 0) {
    chapters[chapters.length - 1].finished = false
  }

  return chapters
}

export default {
  props: {
    content: { type: String, default: '' },
    files: { type: Array, default: null },
    project: { type: Object, default: null },
    chat: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    documentId: { type: String, default: '' },
    message: { type: Object, default: null }
  },
  emits: [
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'sub-task',
    'copy-chapter',
    'create-task'
  ],
  data() {
    return {}
  },
  computed: {
    chapters() {
      return parseChapters(this.content || '', this.loading)
    },
    docProject() {
      return this.project || this.$project
    }
  },
  methods: {
    handleCopyChapter(chapterData) {
      this.$emit('copy-chapter', chapterData)
    },
    handleCreateTask(taskData) {
      this.$emit('create-task', taskData)
    }
  }
}
</script>
