                <path d="M7 7h10M7 11h10M7 15h4" />
              </svg>
            </label>
          </div>

          <!-- Interactive table component -->
          <InteractiveTable 
            v-if="element.viewMode === 'interactive'"
            :initial-data="element.data"
            :table-index="idx"
            @update-table="handleTableUpdate"
          />

          <!-- Standard markdown table -->
          <div 
            v-else
            v-html="element.markdownHtml"
          ></div>
        </div>
      </div>
