    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'sub-task',
    'copy-chapter',
    'create-task'
  ],
  data() {
    return {}
  },
  computed: {
    chapters() {
      return parseChapters(this.content || '', this.loading)
    },
    docProject() {
      return this.project || this.$project
    }
  },
  methods: {
    handleCopyChapter(chapterData) {
      this.$emit('copy-chapter', chapterData)
    },
    handleCreateTask(taskData) {
      this.$emit('create-task', taskData)
    }
  }
}
</script>
